function accept(next){if(!next||room&&(next.code!==room.code||next.revision<=room.revision))return;if(dragUpdates.defer(next))return;rememberFieldReturns(room,next);const flights=prepareFlights(unseenMoves(room,next));const old=room?.state;let changed=!old||!next.state||old.turn!==next.state.turn||old.turns!==next.state.turns||room?.dealDecision?.player!==next.dealDecision?.player;if(changed){clearChoice();if(next.state)passed=!needsLocalPass(next);}room=next;render();flyCards(flights);}
