 document.querySelectorAll('[data-rule]').forEach(el=>el.onclick=()=>run(()=>{const raw=el.dataset.ruleValue,value=raw==='true'?true:raw==='false'?false:['opening','handBonus','cutBonus','dealDuplicateLimit','redealDuplicateLimit'].includes(el.dataset.rule)?Number(raw):raw;return update(el.dataset.rule==='dealDuplicateLimit'&&value?{dealDuplicateLimit:value,redealDuplicateLimit:0}:{[el.dataset.rule]:value});}));

 if($('hand-rules-toggle'))$('hand-rules-toggle').onclick=()=>{handRulesExpanded=!handRulesExpanded;const button=$('hand-rules-toggle');button.classList.toggle('chosen',handRulesExpanded);button.setAttribute('aria-pressed',String(handRulesExpanded));button.setAttribute('aria-expanded',String(handRulesExpanded));$('hand-rule-settings').hidden=!handRulesExpanded;};
 if(!room.state)return;
 document.querySelectorAll('[data-unit]').forEach(el=>{el.onclick=e=>{if(e.target.closest('[data-split],.eject-card')||!passed)return;fieldSelection.clear();dismissNewCards(handLayout[Number(el.dataset.unit)]);const result=selectUnit(handLayout,[...selection],Number(el.dataset.unit));handLayout=result.layout;selection=new Set(result.selected);saveLayout();render();};el.onkeydown=e=>{if(e.target===el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();el.click();}};});
