 document.querySelectorAll('[data-eject-hand]').forEach(el=>el.onclick=e=>{e.stopPropagation();handLayout=ungroupCards(handLayout,[el.dataset.ejectHand]);selection.clear();saveLayout();render();});
 document.querySelectorAll('[data-eject-field]').forEach(el=>el.onclick=e=>{e.stopPropagation();run(()=>action({type:'field-eject',index:Number(el.dataset.ejectField),id:el.dataset.ejectId}));});
 document.querySelectorAll('[data-return-field]').forEach(el=>el.onclick=e=>{e.stopPropagation();run(()=>action({type:room.options.variant==='rummikub'?'rk-split':'field-return',index:Number(el.dataset.returnField)}));});
 document.querySelectorAll('[data-field-group]').forEach(el=>{el.onclick=e=>{if(e.target.closest('.pack-close,.eject-card')||!passed||Number(el.dataset.fieldOwner)!==playerIndex()||!movementContext()?.own)return;selection.clear();const index=Number(el.dataset.fieldGroup),g=room.state.fieldGroups[index];if(g.cards.every(c=>fieldSelection.has(c.id))){fieldSelection.clear();render();return;}const chosen=(room.state.fieldGroups||[]).map((g,i)=>g.cards.some(c=>fieldSelection.has(c.id))?i:-1).filter(i=>i>=0),ids=[...fieldSelection,...g.cards.map(c=>c.id)];if(!chosen.length){fieldSelection=new Set(g.cards.map(c=>c.id));render();return;}run(async()=>{await action({type:'field-group',indices:[...chosen,index]});const remaining=new Set((room.state.fieldGroups||[]).flatMap(g=>g.cards.map(c=>c.id)));fieldSelection=new Set(ids.filter(id=>remaining.has(id)));render();});};el.onkeydown=e=>{if(e.target===el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();el.click();}};});
 document.querySelectorAll('[data-table-meld]').forEach(el=>{el.onclick=e=>{if(e.target.closest('.table-meld-controls'))return;const index=Number(el.dataset.tableMeld);selectedMeld=selectedMeld===index?null:index;render();};el.onkeydown=e=>{if(e.target===el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();el.click();}};});
 if($('ungroup-all'))$('ungroup-all').onclick=()=>{handLayout=handLayout.flatMap(unit=>unit.map(id=>[id]));selection.clear();saveLayout();render();};
