// Acknowledgement updates the badge in place so it cannot interrupt a drag.
document.addEventListener('pointerover',e=>{const shell=e.target.closest('.hand-card-shell[data-new-card]');if(shell)dismissNewCards([shell.dataset.newCard]);});
document.addEventListener('pointerdown',e=>{const unit=e.target.closest('.movement-game [data-unit]');if(unit)dismissNewCards(handLayout[Number(unit.dataset.unit)]||[]);},true);
function movementContext(){if(!room?.state||room.state.winner!==null||room.dealDecision)return null;const p=playerIndex();return {code:room.code,revision:room.revision,layout:layoutKey(),hand:handLayout.map(unit=>unit.join(',')).join('|'),field:(room.state.fieldGroups||[]).map(g=>g.owner+':'+g.cards.map(c=>c.id).join(',')).join('|'),player:p,own:room.state.turn===p&&room.seatTypes[p]!=='bot',passed,busy};}
installCardMovement({context:movementContext,drop:(source,target)=>run(async()=>{
 const current=movementContext(),local=source.stage===null&&source.field===null&&['merge','reorder'].includes(target.type);if(!current||current.code!==source.context.code||current.layout!==source.context.layout||current.hand!==source.context.hand||current.field!==source.context.field||!local&&current.revision!==source.context.revision)throw Error('The table changed while you were moving. Try again.');
 if(source.stage!==null){if(!['merge','reorder'].includes(target.type))return;await action({type:'unstage-open',index:source.stage});return;}
 const fromField=source.field!==null,ids=fromField?room.state.fieldGroups[source.field]?.cards.map(c=>c.id):handLayout[source.unit];if(!ids)return;
 if(['merge','reorder'].includes(target.type)){
  if(fromField){if(room.options.variant==='rummikub'&&ids.some(id=>room.state.melds.some(m=>m.cards.some(c=>c.id===id))))throw Error('Table tiles stay on the field. Split the group to rearrange them.');await action({type:'field-return',index:source.field});if(target.type==='merge'){const recipient=handLayout.findIndex(unit=>unit.some(id=>target.ids?.includes(id)));if(recipient>=0){const joined=[...handLayout[recipient],...ids];handLayout=handLayout.filter(unit=>!unit.some(id=>joined.includes(id)));handLayout.splice(recipient,0,joined);}}else{const moving=handLayout.map((unit,i)=>unit.some(id=>ids.includes(id))?i:-1).filter(i=>i>=0);const rest=handLayout.filter((_,i)=>!moving.includes(i));rest.splice(Math.min(target.before,rest.length),0,[...ids]);handLayout=rest;}}else handLayout=target.type==='merge'?mergeUnits(handLayout,source.unit,target.index,target.position??null):moveUnit(handLayout,source.unit,Number.isFinite(target.before)?target.before:handLayout.length);saveLayout();render();return;
 }
 if(target.type==='return'&&fromField)return action({type:'field-return',index:source.field});
 if(!current.own)throw Error('Wait for your turn to play cards.');
 try{
  if(target.type==='field-merge')return await action({type:'field-merge',index:target.index,...(fromField?{source:source.field}:{ids}),position:target.position});
  if(target.type==='field-reorder'&&fromField)return await action({type:'field-reorder',index:source.field,before:target.before});
  if(target.type==='field'||target.type==='field-reorder'){if(!fromField)return await action({type:'field-stage',ids,...(target.type==='field-reorder'?{before:target.before}:{})});return;}
  const move=target.type==='discard'?{type:'discard'}:target.type==='replace'?{type:'replace',index:target.index,jokerId:target.jokerId}:{type:'layoff',index:target.index};
  const forget=target.type==='discard'?rememberDragDiscards(source.dropRects):()=>{};try{return await action({type:'field-play',...(fromField?{source:source.field}:{ids}),move});}finally{forget();}
 }catch(error){if(error.status===400){if(fromField)await action({type:'field-return',index:source.field});rememberReturns(room,ids);selection.clear();fieldSelection.clear();render();}throw error;}
})});

function join(code){run(async()=>enter(await api('join',{code:code.trim().toLowerCase(),name:$('name').value})));}
function discardPanel(cards){return `<p class="discard-history-summary">${cards.length} card${cards.length===1?'':'s'} currently in the discard pile.</p><p class="discard-history-order">Newest first · top of the pile first.</p>${cards.length?`<ol class="discard-history">${[...cards].reverse().map((c,i)=>`<li><span class="discard-position">${i===0?'Top card':'#'+(i+1)}</span><div class="card ${c.joker?'joker':''}" data-card="${c.id}" tabindex="0" role="img" aria-label="${esc(c.joker?'Joker':rankLabel(c.rank)+' of '+animals[c.suit].name)}">${cardMarkup(c).replace(/curve-joker-[a-z0-9-]+/g,id=>id+'-history')}</div></li>`).join('')}</ol>`:'<p class="discard-empty">Nothing has been discarded yet.</p>'}`;}
function closePanel(restoreFocus=true){const trigger=panel==='discards'?$('discard-history'):$(panel);panel=null;$('floating').hidden=true;$('floating').classList.remove('discard-panel');for(const id of ['timer','undo-settings','score','log','discard-history'])$(id)?.setAttribute('aria-expanded','false');if(restoreFocus&&trigger?.isConnected)trigger.focus({preventScroll:true});}
function togglePanel(name){if(panel===name){closePanel();return;}const keyboard=(name==='discards'?$('discard-history'):$(name))?.matches(':focus-visible');closePanel(false);panel=name;renderPanel();if(keyboard)$('panel-close').focus({preventScroll:true});}
function renderPanel(){if(!room||panel==='undo-settings'&&room.phase!=='lobby'){closePanel(false);return;}const content=$('panel-content'),scrollTop=content.scrollTop,focusedCard=document.activeElement?.closest('.discard-history .card')?.dataset.card;const title={discards:'Discard pile',timer:'Turn timer','undo-settings':'Undo move',score:'Table scoreboard',log:'Game log'}[panel];$('panel-title').textContent=title;$('floating').hidden=false;$(panel==='discards'?'discard-history':panel)?.setAttribute('aria-expanded','true');$('floating').classList.toggle('discard-panel',panel==='discards');const host=room.you===room.host&&room.phase==='lobby';
 if(panel==='timer')$('panel-content').innerHTML=`<div class="timer-options">${[[0,'No timer'],[30,'30 seconds'],[60,'1 minute'],[120,'2 minutes']].map(([n,label])=>`<button data-timer="${n}" class="${room.options.timer===n?'chosen':''}" ${room.you===room.host?'':'disabled'}>${label}</button>`).join('')}</div><p>The host can change the timer at any time. A new duration gives the current turn a fresh countdown. On timeout, a legal turn is completed automatically.</p>`;
 if(panel==='undo-settings')$('panel-content').innerHTML=`<div class="undo-options"><button data-undo="true" class="purple ${room.options.undo?'chosen':''}" ${host?'':'disabled'}>Enable Undo</button><button data-undo="false" class="rose ${!room.options.undo?'chosen':''}" ${host?'':'disabled'}>Disable undo</button></div><p>Undo your latest action using the move button above your hand.</p>`;
 if(panel==='score'&&!room.completedGames){$('panel-content').innerHTML='<p>Results appear after the first completed game.</p>';return;}
 if(panel==='score'){const names=room.state?.names||room.players,winners=cupWinners(room),roundOnly=room.options.winEnabled&&room.options.winMode==='round',scores=roundOnly?(room.roundResults?.at(-1)?.scores||room.totals):room.totals;$('panel-content').innerHTML=`<p>${roundOnly?'Last round’s scores.':'Cumulative round scores.'}</p><ol class="score-rows">${names.map((n,i)=>`<li><span>${winners.includes(i)?cupMarkup:''}${esc(n||'Empty seat')}</span><strong>${scores[i]||0}</strong></li>`).join('')}</ol>`;}


 if(panel==='discards')$('panel-content').innerHTML=discardPanel(room.state?.discard||[]);
 if(panel==='log')$('panel-content').innerHTML=`<ol>${(room.state?.log||['Waiting for the host.']).map(t=>'<li>'+esc(t)+'</li>').join('')}</ol>`;
 content.scrollTop=scrollTop;if(focusedCard)(content.querySelector(`[data-card="${focusedCard}"]`)||$('panel-close')).focus({preventScroll:true});
 document.querySelectorAll('[data-timer]').forEach(el=>el.onclick=()=>run(()=>update({timer:Number(el.dataset.timer)})));
 document.querySelectorAll('[data-undo]').forEach(el=>el.onclick=()=>run(()=>update({undo:el.dataset.undo==='true'})));
}
function renderIndicators(){if(!room)return;$('timer-status').hidden=!room.options.timer;$('undo-status').hidden=room.options.undo;$('timer-status').innerHTML=ClockIcon+`<small id="timer-status-label">${room.options.timer?room.options.timer+' sec':'Off'}</small>`;$('timer-status').setAttribute('aria-label',room.options.timer?'Turn timer '+room.options.timer+' seconds':'Turn timer disabled');$('undo-status').innerHTML=UndoIcon+(room.options.undo?'':cross);$('undo-status').setAttribute('aria-label',room.options.undo?'Undo enabled':'Undo disabled');}
function renderSound(){$('sound').innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 17V5l11-2v12M9 9l11-2" fill="none" stroke="currentColor" stroke-width="2"/><path d="M3 16h6v5H3zm11-2h6v5h-6z" fill="currentColor"/>${muted?'<path d="M3 3l18 18" stroke="#ba4949" stroke-width="3"/>':''}</svg>`;$('sound').setAttribute('aria-label',muted?'Unmute sounds':'Mute sounds');}
for(const[id,icon,label]of [['timer',ClockIcon,'Turn timer'],['undo-settings',UndoIcon,'Enable or disable Undo move'],['leave',LeaveIcon,'Leave table'],['log',ScrollIcon,'Game log']])$(id).innerHTML=icon+`<span class="control-label">${label}</span>`;
$('score').innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3h10v9l-3 3h-1v4h4v3H7v-3h4v-4h-1l-3-3V3zM7 5H3v5l4 3m10-8h4v5l-4 3" fill="none" stroke="currentColor" stroke-width="2"/></svg><span class="control-label">Table scoreboard</span>';
for(const id of ['timer','undo-settings','score','log'])$(id).onclick=()=>togglePanel(id);
$('panel-close').onclick=closePanel;$('close').onclick=()=>$('modal').close();$('modal').onclick=e=>{if(e.target===$('modal'))$('modal').close();};
function applySimpleCards(enabled){const name=$('name')?.value,code=$('join-code')?.value;simpleCards=enabled;setSimpleCards(simpleCards);render();if(!room){$('name').value=name??'';$('join-code').value=code??'';}}
$('simple-cards').onclick=()=>{if(room)return;localStore.setItem('forest-simple-cards',String(!simpleCards));applySimpleCards(!simpleCards);};
window.addEventListener('storage',e=>{if(e.key==='forest-simple-cards')applySimpleCards(e.newValue==='true');});
$('sound').onclick=()=>{muted=!muted;localStore.setItem('forest-muted',muted);renderSound();sound();};renderSound();
$('copy').onclick=()=>run(async()=>{try{await navigator.clipboard.writeText(room.code.toUpperCase());notice('Table code copied: '+room.code.toUpperCase());}catch{notice('Table code: '+room.code);}});
function leave(){modal(`<h2>Leave this table?</h2><p>${room.mode==='online'?'A bot plays your seat for the rest of a running game. If you are the host, the next player becomes host. The table closes when its last player leaves.':'This closes the table and ends its game.'}</p><button id="confirm-leave" class="rose">Leave table</button>`);$('confirm-leave').onclick=()=>run(async()=>{await api('leave',{});dragUpdates.clear();room=null;auth=null;saved=null;sessionStore.removeItem('forest-code');sessionStore.removeItem('forest-token');$('modal').close();closePanel();passed=true;clearChoice();render();});}
$('leave').onclick=leave;
$('help').onclick=()=>room?.options.variant==='rummikub'?modal(rummikubHelp()):modal(`<h2>Field-building playtest</h2><p>Click cards or groups to select and join them, in your hand or on the field. Hold and pull to move. Drop onto cards to combine; drop into gaps to rearrange. Click elsewhere to stop grouping.</p><p>After drawing and after the first lap, move loose cards or groups onto the green field and build there. Everyone can see unfinished groups, but only their owner can edit them. Legal groups lay automatically after opening. Before opening, valid groups combine automatically at the required total.</p><p>Hover any card in a hand group or unfinished field group for its red x. Clicking it sends that card to its own loose hand unit. The group’s left x separates the whole group. Permanent melds have no removal x.</p><p>Invalid additions and exchanges return their source cards. Discarding first returns unfinished field groups; a legal discard then ends the turn. Cards returned from the field have a light-blue Returned badge until hovered, clicked or moved.</p><p>After opening, drag additions onto table melds and exact replacement cards onto jokers. Click a permanent meld to show its controls. Keep a final discard; opening and the other table rules still apply. The Discard label shows the current pile, newest first.</p>`);

function tick(){if(room?.nextRoundAt)document.querySelectorAll('[data-round-countdown]').forEach(el=>{el.textContent='New round starting in '+Math.max(1,Math.ceil((room.nextRoundAt-Date.now())/1000))+'…';});const s=room?.state,el=$('timer-status-label');if(!el||!s||!room.options.timer||s.winner!==null)return;if(room.dealDecision){el.textContent='Paused';$('timer-status').classList.remove('urgent');return;}const left=Math.max(0,Math.ceil((s.turnStarted+room.options.timer*1000-Date.now())/1000));el.textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');$('timer-status').classList.toggle('urgent',left<10);}
document.addEventListener('click',e=>{if(room?.phase==='game'&&(selection.size||fieldSelection.size)&&!e.target.closest('[data-card],[data-unit],[data-field-group]')){selection.clear();fieldSelection.clear();render();}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]')){const trigger=panel==='discards'?'discard-history':panel;closePanel(false);clearChoice();if(room)render();if(trigger)$(trigger)?.focus({preventScroll:true});}});
setInterval(tick,500);
let failures=0,pollTimer=null,pollAgain=false;
async function poll(){
 if(polling)return;polling=true;let delay=0;const code=room?.code||saved;
 try{
  if(!room&&saved&&auth){accept(await api('state?code='+saved));}
  if(room){const next=await api('state?code='+room.code+'&since='+room.revision);if(room?.code===code&&next)accept(next);}
  else if(!document.hidden){const next=await api('tables');if(!room&&JSON.stringify(next)!==JSON.stringify(tables)){tables=next;const list=document.querySelector('.open-tables');if(list){list.innerHTML=tableList();list.querySelectorAll('[data-join]').forEach(el=>el.onclick=()=>join(el.dataset.join));}}delay=15000;}
  else delay=15000;
  failures=0;
 }catch(e){
  if(room?.code===code&&e.status===400){dragUpdates.clear();room=null;auth=null;saved=null;sessionStore.removeItem('forest-code');sessionStore.removeItem('forest-token');clearChoice();closePanel();render();notice(e.message);delay=15000;}
  else{delay=Math.min(30000,1200*2**failures++);if(failures===1&&room)notice('Connection lost. Reconnecting…');}
 }finally{polling=false;pollTimer=setTimeout(poll,pollAgain?0:delay);pollAgain=false;}
}
function wakePoll(){clearTimeout(pollTimer);if(polling)pollAgain=true;else poll();}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)wakePoll();});
render();
async function restore(){if(saved&&auth)try{accept(await api('state?code='+saved));}catch(e){if(e.status===400){sessionStore.removeItem('forest-code');sessionStore.removeItem('forest-token');saved=null;auth=null;}else notice('The forest is unreachable right now. Reconnecting…');}poll();}
restore();
